 "content": "from math import gcd
from functools import reduce


def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]

    # The small colored pattern is the source; the large 8-pattern is its
    # clockwise-rotated enlargement, with each colored cell expanded uniformly.
    colored = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    r0m = min(r for r, c in colored)
    c0m = min(c for r, c in colored)
    r1m = max(r for r, c in colored)
    c1m = max(c for r, c in colored)
    pattern = [row[c0m:c1m + 1] for row in grid[r0m:r1m + 1]]
    rotated = [list(row) for row in zip(*pattern[::-1])]

    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    # Infer the square enlargement factor from horizontal/vertical runs of 8s.
    runs = []
    for r in range(h):
        xs = [c for rr, c in cells if rr == r]
        if xs:
            n = 1
            for a, b in zip(xs, xs[1:]):
                if b == a + 1:
                    n += 1
                else:
                    runs.append(n)
                    n = 1
            runs.append(n)
    for c in range(w):
        ys = [r for r, cc in cells if cc == c]
        if ys:
            n = 1
            for a, b in zip(ys, ys[1:]):
                if b == a + 1:
                    n += 1
                else:
                    runs.append(n)
                    n = 1
            runs.append(n)
    scale = reduce(gcd, runs)

    out = [row[:] for row in grid]
    for pr, row in enumerate(rotated):
        for pc, color in enumerate(row):
            if color == 0:
                continue
            rr, cc = r0 + pr * scale, c0 + pc * scale
            for dr in range(scale):
                for dc in range(scale):
                    if rr + dr < h and cc + dc < w and out[rr + dr][cc + dc] == 8:
                        out[rr + dr][cc + dc] = color
    return out
